def solve(data):
    cutoff = data.get('cutoff', 10**9)
    winners = {}

    for position, event in enumerate(data['events']):
        if event.get('sequence', 0) > cutoff:
            continue

        key = ('id', event['id']) if 'id' in event else ('anonymous', position)
        revision = event.get('revision', 0)
        previous = winners.get(key)
        if previous is None or (revision, position) > (previous[0], previous[1]):
            winners[key] = (revision, position, event)

    balances = dict(data.get('opening', {}))
    for _, _, event in winners.values():
        if event.get('void', False):
            continue
        account = event.get('account', 'default')
        currency = event.get('currency', 'USD')
        key = f'{account}|{currency}'
        balances.setdefault(key, 0)
        balances[key] += amount(event, data['rounding'])

    return {'balances': balances}
